(()=>{'use strict';
const KEY='last-shuttle-playtest-v6',R=3,HOME='0,0',DROPSHIP='3,-2',NEST='-3,3';
const DIRS=[[1,0],[1,-1],[0,-1],[-1,0],[-1,1],[0,1]];
const CELLS=[];for(let q=-R;q<=R;q++)for(let r=-R;r<=R;r++)if(Math.abs(q+r)<=R)CELLS.push({q,r,k:`${q},${r}`});
const MAP=Object.fromEntries(CELLS.map(c=>[c.k,c]));
const COLOURS=['#ffd36d','#67d7e7','#ff8b7c','#bd9af3','#8ce0a4','#fa9bc2'];
const CAPTURE_ART='data:image/jpeg;base64,';
const USABLE=['flare','jetpack','scanner','medkit'];
const rank=i=>i===0?'SGT':'MARINE';
const personnel=i=>`RSM-${String(i+1).padStart(3,'0')}`;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dist=(a,b)=>{let A=MAP[a],B=MAP[b];return Math.max(Math.abs(A.q-B.q),Math.abs(A.r-B.r),Math.abs(A.q+A.r-B.q-B.r))};
const ring=k=>{let c=MAP[k];return Math.max(Math.abs(c.q),Math.abs(c.r),Math.abs(c.q+c.r))};
const shuffle=a=>{for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const take=a=>a.splice(Math.floor(Math.random()*a.length),1)[0];
let s;try{s=JSON.parse(localStorage.getItem(KEY))}catch{}
if(s){for(let t of Object.values(s.tiles))if(t.terrain==='shuttle')t.terrain='dropship';s.alienMind??={mode:'stalk',target:null,stalked:0};s.flares??=[];for(let p of s.players)p.researchEffect??=null}
let ui={selected:HOME,mode:'',note:'',private:false,privateKind:'',privateResult:'',scan:false,transfer:false,itemIndex:null,targetHex:null,escapeRoll:null,flipping:'',revealing:{}};
const tile=k=>s.tiles[k],me=()=>s.players[s.turn];
function save(){localStorage.setItem(KEY,JSON.stringify(s))}function log(t){s.log.unshift(`R${s.round}: ${t}`);s.log=s.log.slice(0,40)}
function notice(t){ui.note=t;render()}function finish(){save();render();if(ui.messages?.length&&!ui.sequence)runMessages()}
function newGame(names){let keys=shuffle(CELLS.filter(c=>![HOME,DROPSHIP,NEST].includes(c.k)).map(c=>c.k));
 let terrain=shuffle([...Array(12).fill('open'),...Array(4).fill('bridge'),...Array(4).fill('gravity'),...Array(3).fill('cover'),...Array(3).fill('spores'),...Array(8).fill('event')]);
 let holes=shuffle(['red','red','blue','blue']);let tiles={};for(let c of CELLS){let type=c.k===HOME?'lander':c.k===DROPSHIP?'dropship':c.k===NEST?'nest':terrain.pop();tiles[c.k]={terrain:type,known:[HOME,DROPSHIP].includes(c.k),pair:type==='gravity'?holes.pop():null,site:null,loose:[],groundScientists:0,eventSpent:false}}
 let sites=shuffle(keys.filter(k=>![HOME,DROPSHIP,NEST].includes(k)));for(let v of shuffle(['scientist','scientist','false','false']))tiles[sites.pop()].site={kind:'distress',value:v,status:'hidden'};
 for(let v of shuffle(['egg','jetpack','flare','scanner','medkit','specimen']))tiles[sites.pop()].site={kind:'cargo',value:v,status:'hidden'};
 let roles=shuffle(['saboteur',...Array(names.length-1).fill('crew')]);
 s={phase:'briefing',round:1,turn:0,moves:2,ap:1,players:names.map((name,i)=>({name,role:roles[i],briefed:false,pos:HOME,scientist:false,cargo:[],researchEffect:null,captive:false,safeNest:false,quietRound:0,rolledRound:0,lastRoll:null})),tiles,alien:NEST,alienMind:{mode:'stalk',target:null,stalked:0},noise:[],lure:null,flares:[],scans:2,delivered:0,eggDestroyed:false,decoys:2,pendingSabotage:[],events:shuffle(['Alien lunge','Bridge tremor','Spore burst','Scan battery','Supply pod','Quiet cover','Risky salvage','Distress coordinates']),pendingEvent:null,alert:'',log:['R1: Find two scientists and keep the egg off the dropship.'],winner:null};
 ui={selected:HOME,mode:'',note:'',private:false,privateKind:'',privateResult:'',scan:false,transfer:false,itemIndex:null,targetHex:null,escapeRoll:null,flipping:'',revealing:{}};finish()}
function reveal(k){let t=tile(k);if(!t||t.known)return;let game=s,revealing=ui.revealing;t.known=true;revealing[k]=true;setTimeout(()=>{if(s!==game)return;delete revealing[k];render()},950)}
function adjacent(k){return DIRS.map(([dq,dr])=>`${MAP[k].q+dq},${MAP[k].r+dr}`).filter(x=>tile(x)&&tile(x).terrain!=='void')}
function spend(){s.ap=Math.max(0,s.ap-1);finish()}
function noise(k){s.noise.push(k)}
function gravityExit(k){let t=tile(k);return t.terrain==='gravity'?Object.keys(s.tiles).find(x=>x!==k&&tile(x).terrain==='gravity'&&tile(x).pair===t.pair):null}
function arrive(k,method){let p=me(),entry=k,exit=gravityExit(k);reveal(entry);if(exit){k=exit;reveal(k)}p.pos=k;p.safeNest=false;ui.selected=k;ui.mode='';ui.note=exit?`The ${tile(entry).pair} Gravity Hole transported you to its pair.`:'';log(`${p.name} ${method}${exit?` and emerged from the ${tile(entry).pair} Gravity Hole`:''}.`);
 if(tile(k).terrain==='spores'){noise(k);log(`Spores at ${k} drew the creature's attention.`)}
 if(k===s.alien)capture();
 if(!p.captive&&tile(k).terrain==='event'&&!tile(k).eventSpent){s.moves=0;triggerEvent(k)}}
function move(k){if(s.phase!=='play'||s.pendingEvent||ui.sequence||ui.popup)return;let p=me();if(p.captive)return notice('You are captive. Roll to escape first.');if(!tile(k)||tile(k).terrain==='void')return notice('That route has collapsed.');if(s.moves<1)return notice('No moves remain this turn.');if(dist(p.pos,k)!==1)return notice('Tap an adjacent hex.');s.moves--;arrive(k,'moved');finish()}
 function capture(){let caught=s.players.filter(p=>p.pos===s.alien&&!p.captive&&!(p.safeNest&&p.pos===NEST));for(let p of caught){let where=p.pos,parts=[];if(p.scientist){p.scientist=false;tile(where).groundScientists++;parts.push('dropped their scientist')}if(p.cargo.length){let drop=where;if(tile(where).terrain==='gravity'){let candidates=adjacent(where).filter(x=>!['gravity','void'].includes(tile(x).terrain));if(!candidates.length)candidates=Object.keys(s.tiles).filter(x=>!['gravity','void'].includes(tile(x).terrain)).sort((a,b)=>dist(a,where)-dist(b,where));drop=take(candidates)}tile(drop).loose.push(...p.cargo.splice(0));parts.push(`dropped all inventory as equipment at ${drop}`)}reveal(NEST);p.pos=NEST;p.captive=true;p.safeNest=false;if(p===me()){s.moves=0;s.ap=0}let msg=`CREATURE CAPTURE: ${p.name} ${parts.length?parts.join(' and ')+', ':''}was taken to the nest.`;s.alert=msg;ui.note=msg;log(msg);ui.messages??=[];ui.messages.push({kind:'capture',title:`${rank(s.players.indexOf(p))} ${p.name} captured`,text:'Taken to the Alien Nest.'+(parts.length?' '+parts.join(' and ')+'.':'' )});s.alienMind={mode:'withdraw',target:null,stalked:0,withdrawUntil:s.round+1}}return caught.length}
function pathTo(start,goal,avoidPeople=false){let queue=[start],seen=new Set(queue),prev={};while(queue.length){let k=queue.shift();if(k===goal){let path=[];while(k!==start){path.unshift(k);k=prev[k]}return path}let options=adjacent(k).sort((a,b)=>Number(tile(a).known)-Number(tile(b).known));for(let n of options){if(seen.has(n)||avoidPeople&&s.players.some(p=>!p.captive&&p.pos===n))continue;seen.add(n);prev[n]=k;queue.push(n)}}return null}
function hiddenRetreat(){let candidates=CELLS.map(c=>c.k).filter(k=>!tile(k).known&&tile(k).terrain!=='void').map(k=>({k,path:pathTo(s.alien,k,true)})).filter(o=>o.path!==null).sort((a,b)=>a.path.length-b.path.length);if(candidates.length)return candidates[0].path[0]||s.alien;let options=[s.alien,...adjacent(s.alien)].filter(k=>!s.players.some(p=>!p.captive&&p.pos===k));let crew=s.players.filter(p=>!p.captive);options.sort((a,b)=>{let gap=k=>crew.length?Math.min(...crew.map(p=>dist(k,p.pos))):0;return gap(b)-gap(a)});return options[0]||s.alien}
function alienDestination(override,remaining=2){let mind=s.alienMind,forced=override||s.lure||s.flares.at(-1)?.hex||s.noise.at(-1);if(forced){let route=pathTo(s.alien,forced);return route?.[0]||s.alien}if(mind.mode==='withdraw')return hiddenRetreat();let eligible=s.players.map((p,i)=>({p,i,path:pathTo(s.alien,p.pos)})).filter(o=>!o.p.captive&&tile(o.p.pos).terrain!=='cover'&&o.p.quietRound!==s.round&&o.path!==null).sort((a,b)=>a.path.length-b.path.length);if(!eligible.length){mind.target=null;mind.stalked=0;return hiddenRetreat()}let chosen=eligible.find(o=>o.i===mind.target)||eligible[0];if(mind.target!==chosen.i){mind.target=chosen.i;mind.stalked=0;mind.mode='stalk'}if(mind.stalked>=1&&chosen.path.length<=remaining||mind.mode==='attack'){mind.mode='attack';return chosen.path[0]||s.alien}mind.mode='stalk';let dark=CELLS.map(c=>c.k).filter(k=>!tile(k).known&&tile(k).terrain!=='void'&&dist(k,chosen.p.pos)>0).map(k=>({k,path:pathTo(s.alien,k,true)})).filter(o=>o.path!==null).sort((a,b)=>(dist(a.k,chosen.p.pos)*2+a.path.length*.5)-(dist(b.k,chosen.p.pos)*2+b.path.length*.5));if(dark.length)return dark[0].path[0]||s.alien;let options=[s.alien,...adjacent(s.alien)].filter(k=>!s.players.some(p=>!p.captive&&p.pos===k));options.sort((a,b)=>Math.abs(dist(a,chosen.p.pos)-2)-Math.abs(dist(b,chosen.p.pos)-2));return options[0]||s.alien}
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function alienStep(targetOverride,remaining=2){let game=s,from=s.alien,to=alienDestination(targetOverride,remaining);ui.alienMotion={from,to,started:Date.now(),duration:1000};render();await pause(1000);if(s!==game)return;ui.alienMotion=null;s.alien=to;if(s.phase==='alien')s.alienMovesLeft=Math.max(0,s.alienMovesLeft-1);capture();save();render();await drainMessages()}
async function showPopup(message){let game=s;ui.popup={...message,fading:false};render();let words=(message.title+' '+message.text).split(/\s+/).length;await pause(Math.max(6000,Math.min(12000,words*270)));if(s!==game)return;ui.popup.fading=true;render();await pause(650);if(s!==game)return;ui.popup=null;render()}
async function drainMessages(){while(ui.messages?.length)await showPopup(ui.messages.shift())}
async function runMessages(){if(ui.sequence)return;ui.sequence=true;await drainMessages();ui.sequence=false;finish()}
function popupMarkup(){if(!ui.popup)return '';let m=ui.popup;return `<div class="event-overlay ${m.fading?'fading':''}" role="dialog" aria-modal="true" aria-label="${esc(m.title)}"><div class="event-window crt ${m.kind==='capture'?'capture-window':''}">${m.kind==='capture'?`<div class="capture-art"><img src="${CAPTURE_ART}" alt="A biomechanical alien grips a Marine's helmet and obscured face"></div>`:'<p class="order-classification">UKSS APATE · FIELD REPORT</p>'}<h2>${esc(m.title)}</h2><p>${esc(m.text)}</p>${m.kind==='capture'?'<blockquote>“Man, their signs are real low, but they ain’t dead.”</blockquote>':''}<div class="popup-timer" aria-hidden="true"></div></div></div>`}

function startNext(i){s.turn=i;s.moves=2;s.ap=1;s.phase='handoff';ui.escapeRoll=null;ui.dieSettled=false;let p=me();if(p.captive){s.ap=0;return}let e=p.researchEffect;if(e){if(e.kind==='adrenal'){s.moves=3;ui.note='Specimen effect: 3 moves this turn.'}if(e.kind==='cognitive'){s.ap=2;ui.note='Specimen effect: 2 actions this turn.'}if(e.kind==='fatigue'){s.moves=1;ui.note='Specimen effect: 1 move this turn.'}if(e.kind==='shutdown'){s.ap=0;ui.note='Neural shutdown: no actions this turn; movement is available.'}e.turns--;if(e.turns<=0)p.researchEffect=null}}
 async function roundEnd(){s.alert='';for(let sabotage of s.pendingSabotage||[]){if(sabotage.type==='jam'&&s.scans>0){s.scans--;log('Scanner interference cost the team one charge.')}if(sabotage.type==='decoy'){let t=tile(sabotage.hex);if(t&&!t.site&&!['void','lander','dropship','nest'].includes(t.terrain)){t.site={kind:'distress',value:'false',status:'hidden',decoy:true};log('A new distress signal appeared.')}}if(sabotage.type==='redirect'){s.lure=sabotage.hex;log('An unexplained signal redirected the creature.')}}s.pendingSabotage=[];s.phase='alien';s.alienMovesLeft=2;save();await runAlienTurn()}
async function runAlienTurn(){if(ui.sequence)return;ui.sequence=true;ui.private=false;ui.privateResult='';ui.flipping='';render();while(s.alienMovesLeft>0){await alienStep(null,s.alienMovesLeft);save()}if(s.alienMind.mode==='stalk')s.alienMind.stalked++;if(s.alienMind.mode==='withdraw'&&s.round>=s.alienMind.withdrawUntil)s.alienMind.mode='stalk';s.lure=null;s.noise=[];s.flares=s.flares.filter(f=>f.untilRound>s.round);for(let p of s.players)p.safeNest=false;
 if(s.round>=9){s.winner='saboteur';s.phase='over';log('The dropship window closed. The saboteur wins.')}else{s.round++;startNext(0)}ui.sequence=false;finish()}
function endTurn(){if(s.phase!=='play'||s.pendingEvent)return;ui.mode='';ui.note='';ui.privateResult='';ui.flipping='';if(s.turn===s.players.length-1)roundEnd();else startNext(s.turn+1);finish()}
function flipEndTurn(){if(ui.sequence||ui.popup||ui.flipping||s.phase!=='play'||s.pendingEvent)return;ui.private=false;ui.privateKind='';ui.privateResult='';ui.flipping='out';render();setTimeout(()=>endTurn(),1000)}
function triggerEvent(k){let event=s.events.shift()||'Quiet cover',t=tile(k);t.terrain='open';t.eventSpent=true;log(`${me().name} triggered an event: ${event}.`);ui.note='';ui.sequence=true;runEvent(event,k)}
async function runEvent(event,k){let description='',target=null;
 if(event==='Alien lunge'){description='The alien lunges one hex towards your position.';target=me().pos}
 if(event==='Bridge tremor'){let choices=Object.keys(s.tiles).filter(x=>canCollapse(x));if(choices.length){let b=take(choices);tile(b).terrain='void';description=`A bridge collapsed at ${b}. Neither Marines nor the alien can cross it.`;log(description)}else description='The ground shakes, but no empty bridge collapses.'}
 if(event==='Spore burst'){noise(k);target=k;description='Spores release a loud burst. The alien moves one hex towards you.'}
 if(event==='Scan battery'){s.scans++;description='Recovered a scan battery. The team gains one scan charge.';log(description)}
 if(event==='Supply pod'){if(me().cargo.length<2){me().cargo.push('flare');description='Recovered a flare. It is now in your inventory.'}else{tile(k).loose.push('flare');description='Recovered a flare. Your inventory is full, so it stays on this hex as equipment.'}log('A flare was recovered.')}
 if(event==='Quiet cover'){me().quietRound=s.round;description='You are hidden from the alien for this hour, unless you make noise.';log(description)}
 if(event==='Risky salvage'){s.pendingEvent=event;description='A jetpack is within reach, but recovering it will draw the alien closer. Choose whether to risk it after this report.'}
 if(event==='Distress coordinates'){s.pendingEvent=event;description='A transmission could locate a distress signal. Decoding it uses one scan charge if available. Choose after this report.'}
 save();await showPopup({kind:'event',title:event,text:description+' Your movement ends here.'});if(target)await alienStep(target,1);ui.sequence=false;finish()}
async function chooseEvent(takeRisk){let event=s.pendingEvent;if(!event||ui.sequence)return;ui.sequence=true;s.pendingEvent=null;let p=me(),text='You left the opportunity untouched.',target=null;if(takeRisk&&event==='Risky salvage'){if(p.cargo.length<2){p.cargo.push('jetpack');text='Recovered a jetpack into your inventory.'}else{tile(p.pos).loose.push('jetpack');text='Inventory full. The recovered jetpack remains here as equipment.'}target=p.pos;text+=' The alien moves one hex towards you.';log(`${p.name} salvaged a jetpack, drawing the creature.`)}
 if(takeRisk&&event==='Distress coordinates'){let hidden=Object.entries(s.tiles).filter(([k,t])=>t.site?.kind==='distress'&&t.site.status==='hidden');if(hidden.length){let [k,t]=take(hidden);if(t.site.value==='false'){t.site.status='cleared';text=`A false distress signal was exposed at ${k}.`}else{t.site.status='found';t.intel=true;text=`A scientist signal was located at ${k}. Terrain remains in darkness.`}}else text='No distress signals remain.';if(s.scans>0){s.scans--;text+=' One scan charge was used.'}log(text)}if(!takeRisk)log(`${p.name} passed on the event offer.`);save();await showPopup({kind:'event',title:event+' — outcome',text});if(target)await alienStep(target,1);ui.sequence=false;finish()}

function search(){let p=me(),t=tile(p.pos);if(s.ap<1||p.captive||!t.site||t.site.status!=='hidden')return;if(t.site.kind==='cargo'&&p.cargo.length>=2)return notice('Inventory full: drop an item first.');let v=t.site.value;t.site.status=v==='scientist'?'found':'cleared';if(t.site.kind==='cargo'){p.cargo.push(v);ui.privateResult=`You found ${v.toUpperCase()}. Added to inventory.`;log(`${p.name} searched an equipment cache.`)}else if(v==='scientist')log(`${p.name} found a scientist.`);else log(`${p.name} found a false distress signal.`);noise(p.pos);spend()}
function escort(){let p=me(),t=tile(p.pos);if(s.ap<1||p.captive||p.scientist)return;if(t.groundScientists)t.groundScientists--;else if(t.site?.value==='scientist'&&t.site.status==='found')t.site.status='rescued';else return;p.scientist=true;log(`${p.name} is escorting a scientist.`);spend()}
function deliver(){let p=me();if(s.ap<1||p.pos!==DROPSHIP||!p.scientist||p.captive)return;p.scientist=false;s.delivered++;log(`${p.name} delivered scientist ${s.delivered}/2.`);spend()}
function escapeNest(){let p=me();if(ui.rolling||!p.captive||s.phase!=='play'||p.rolledRound===s.round)return;ui.rolling=true;ui.escapeRoll=null;let game=s;render();setTimeout(()=>{if(s!==game||me()!==p||s.phase!=='play')return;let n=1+Math.floor(Math.random()*6);ui.rolling=false;ui.dieSettled=true;ui.escapeRoll=n;p.rolledRound=s.round;p.lastRoll=n;s.ap=0;if(n%2===0){p.captive=false;p.safeNest=true;s.moves=2;ui.note=`Alien die: ${n}. You escaped! Take two moves; no action this turn.`;log(`${p.name} rolled ${n} and escaped the nest.`)}else{s.moves=0;ui.note=`Alien die: ${n}. Still captive. Your turn is ending.`;log(`${p.name} rolled ${n} and remains captive.`)}finish();setTimeout(()=>{if(s!==game||me()!==p)return;ui.dieSettled=false;if(n%2&&s.phase==='play'&&p.captive)flipEndTurn();else render()},1800)},1500)}
function freeCaptive(i){let p=me(),other=s.players[i];if(s.ap<1||p.captive||!other?.captive||dist(p.pos,NEST)>1)return;other.captive=false;other.safeNest=true;log(`${p.name} freed ${other.name} from the nest.`);spend()}
function drop(i){let p=me();if(s.ap<1||p.captive||!p.cargo[i])return;tile(p.pos).loose.push(p.cargo.splice(i,1)[0]);log(`${p.name} dropped an inventory item as equipment.`);spend()}
function collect(i){let p=me(),a=tile(p.pos).loose;if(s.ap<1||p.captive||p.cargo.length>=2||!a[i])return;p.cargo.push(a.splice(i,1)[0]);ui.privateResult=`You picked up ${p.cargo.at(-1).toUpperCase()} into inventory.`;log(`${p.name} picked up equipment.`);spend()}
function validItemTarget(v,k){return !!tile(k)&&tile(k).terrain!=='void'&&(v==='flare'?dist(me().pos,k)<=3:v==='jetpack'?dist(me().pos,k)>=1&&dist(me().pos,k)<=3:v==='scanner'?k===me().pos:v==='medkit'?k===HOME:false)}
function beginItem(i){let v=me().cargo[i];if(s.ap<1||me().captive||!USABLE.includes(v))return;ui.private=false;ui.privateKind='';ui.itemIndex=i;ui.targetHex=null;ui.mode='itemTarget';ui.note=`Choose a target hex for ${v.toUpperCase()}. Highlighted hexes are valid. Confirm or cancel before the item is used.`;render()}
function cancelTarget(){ui.mode='';ui.itemIndex=null;ui.targetHex=null;ui.note='';render()}
function useItem(){let p=me(),i=ui.itemIndex,v=p.cargo[i],k=ui.targetHex;if(s.ap<1||p.captive||!validItemTarget(v,k))return notice('Select a highlighted target hex.');p.cargo.splice(i,1);s.ap--;ui.mode='';ui.itemIndex=null;ui.targetHex=null;ui.note='';
 if(v==='flare'){s.flares.push({hex:k,untilRound:s.round+1});log(`${p.name} fired a flare towards ${k}. The creature will follow it this round and next.`)}
 if(v==='jetpack'){noise(k);arrive(k,'landed by jetpack')}
 if(v==='scanner'){s.scans++;log(`${p.name} recharged the scanner.`)}
 if(v==='medkit'){p.pos=HOME;log(`${p.name} returned to the lander with a medkit.`);if(p.pos===s.alien)capture()}
 finish()}
function researchSpecimen(i){let p=me();if(s.ap<1||p.captive||p.cargo[i]!=='specimen')return;let roll=Math.random(),kind=roll<.35?'adrenal':roll<.70?'cognitive':roll<.90?'fatigue':'shutdown',messages={adrenal:'Adrenal surge: 3 moves on your next free turn.',cognitive:'Cognitive surge: 2 actions on your next free turn.',fatigue:'Muscle fatigue: 1 move on your next free turn.',shutdown:'Neural shutdown: no actions on your next two free turns. You can still move.'};p.cargo.splice(i,1);p.researchEffect={kind,turns:kind==='shutdown'?2:1};s.ap--;ui.privateResult=messages[kind];ui.privateKind='';ui.private=true;log(`${p.name} researched a specimen. Results are private.`);finish()}
function incinerate(i){let p=me();if(s.ap<1||p.captive||p.pos!==HOME||!p.cargo[i])return;let v=p.cargo.splice(i,1)[0];if(v==='egg')s.eggDestroyed=true;log(`${p.name} incinerated ${v==='egg'?'THE EGG':`a ${v}`}.`);noise(HOME);spend()}
function scan(pi,i){let p=me(),other=s.players[pi];if(s.ap<1||p.captive||s.scans<1||!other||p.pos!==other.pos||!other.cargo[i])return notice('Stand with an inventory holder to scan.');let v=other.cargo[i];s.scans--;log(`${p.name} scanned ${other.name}'s inventory ${i+1}: ${v.toUpperCase()}.`);if(v==='egg'){other.cargo.splice(i,1);s.eggDestroyed=true;log('The egg was confiscated and destroyed.')}ui.note=`Scan inventory ${i+1}: ${v.toUpperCase()}${v==='egg'?' — destroyed':''}`;ui.scan=false;spend()}
function transfer(pi,i,steal){let p=me(),other=s.players[pi];if(s.ap<1||p.captive||!other||pi===s.turn||dist(p.pos,other.pos)>(steal?1:0))return;if(steal){if(!other.cargo.length||p.cargo.length>=2)return;let j=Math.floor(Math.random()*other.cargo.length);p.cargo.push(other.cargo.splice(j,1)[0]);ui.privateResult=`You snatched ${p.cargo.at(-1).toUpperCase()}.`;log(`${p.name} snatched a random inventory item from ${other.name}.`)}else{if(!p.cargo[i]||other.cargo.length>=2)return;other.cargo.push(p.cargo.splice(i,1)[0]);log(`${p.name} passed an inventory item to ${other.name}.`)}ui.transfer=false;spend()}
function canCollapse(k){let t=tile(k);return t?.terrain==='bridge'&&!t.site&&!t.groundScientists&&!t.loose.length&&!s.players.some(p=>p.pos===k)&&s.alien!==k}
function collapse(k){let p=me();if(s.ap<1||p.captive||dist(p.pos,k)>1||!canCollapse(k))return notice('Choose an adjacent empty bridge.');tile(k).terrain='void';tile(k).known=true;log(`${p.name} collapsed a bridge at ${k}.`);spend()}
function jamScan(){if(me().role!=='saboteur'||s.ap<1||me().captive||s.scans<1)return;s.pendingSabotage.push({type:'jam'});ui.private=false;ui.privateKind='';s.ap--;ui.note='Your interference is queued for the end of this round.';finish()}
function plant(k){let p=me(),t=tile(k);if(p.role!=='saboteur'||s.ap<1||p.captive||s.decoys<1||dist(p.pos,k)>1||!t||t.site||['void','lander','dropship','nest'].includes(t.terrain))return notice('Choose an adjacent empty hex.');s.pendingSabotage.push({type:'decoy',hex:k});s.decoys--;ui.mode='';ui.note='False signal queued for round end.';s.ap--;finish()}
function redirect(k){let p=me();if(p.role!=='saboteur'||s.ap<1||p.captive||!tile(k)||dist(p.pos,k)>2)return notice('Choose a hex within two spaces.');s.pendingSabotage.push({type:'redirect',hex:k});ui.mode='';ui.note='Creature redirection queued for round end.';s.ap--;finish()}
function launch(){if(s.phase!=='play'||s.delivered!==2||me().pos!==DROPSHIP||s.ap<1||me().captive)return;s.phase='launch';finish()}
function finishLaunch(){let people=[...document.querySelectorAll('.boarding:checked')].map(e=>+e.value);if(!people.length)return notice('Choose at least one passenger.');s.winner=people.some(i=>s.players[i].cargo.includes('egg'))?'saboteur':'crew';s.phase='over';log(s.winner==='crew'?'The scientists escaped without the egg. Crew win.':'THE EGG BOARDED. Saboteur wins.');finish()}
const label=t=>({lander:'Lander',dropship:'Dropship',nest:'Alien nest',open:'Open ground',bridge:'Bridge',gravity:'Gravity Hole',cover:'Cover',spores:'Spore field',event:'Event tile',void:'Collapsed hex'})[t]||t;
function hexInfo(k){let t=tile(k);if(!t.known)return `<div class="notice"><strong>Unexplored</strong> · ${k} · terrain unexplored</div>`;return `<div class="notice"><strong>${t.terrain==='gravity'?`${t.pair==='red'?'Red':'Blue'} Gravity Hole`:label(t.terrain)}</strong> · ${k}${t.site?.status==='hidden'?` · ${t.site.kind==='cargo'?'equipment cache':'distress signal'}`:''}${t.site?.status==='found'||t.groundScientists?' · scientist waiting':''}${t.loose.length?` · ${t.loose.length} dropped equipment`:''}${k===s.alien?' · CREATURE HERE':''}</div>`}
function targetValid(k){if(ui.mode==='itemTarget')return validItemTarget(me().cargo[ui.itemIndex],k);if(ui.mode==='decoy'){let t=tile(k);return !!t&&dist(me().pos,k)<=1&&!t.site&&!['void','lander','dropship','nest'].includes(t.terrain)}if(ui.mode==='redirect')return !!tile(k)&&dist(me().pos,k)<=2;return false}
const EMBEDDED_TILE_ART={"alien-nest":"data:image/jpeg;base64,","bridge":"data:image/jpeg;base64,","collapsed-bridge":"data:image/jpeg;base64,","cover":"data:image/jpeg;base64,","event":"data:image/jpeg;base64,","gravity-blue":"data:image/jpeg;base64,","gravity-red":"data:image/jpeg;base64,","lander":"data:image/png;base64,","open-ground":"data:image/jpeg;base64,","dropship":"data:image/png;base64,","spore-field":"data:image/jpeg;base64,"};
function tileArt(t){let name=t.terrain==='gravity'?`gravity-${t.pair}`:({open:'open-ground',bridge:'bridge',cover:'cover',spores:'spore-field',event:'event',lander:'lander',dropship:'dropship',nest:'alien-nest',void:'collapsed-bridge'})[t.terrain];return EMBEDDED_TILE_ART[name]}
const artCache=new Map(),artFailures=new Set();
function artwork(src){if(!artCache.has(src)){let img=new Image();img.onload=drawTerrain;img.onerror=()=>{artFailures.add(src);drawTerrain()};img.src=src;artCache.set(src,img)}return artCache.get(src)}
function drawTerrain(){let canvas=document.querySelector('.terrain-canvas');if(!canvas||!s)return;let ctx=canvas.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,680,614);const S=55,W=2*S*1346/1168;
 for(let c of CELLS){let t=tile(c.k),x=360+Math.sqrt(3)*S*(c.q+c.r/2)-20,y=315+1.5*S*c.r-8;ctx.save();ctx.beginPath();for(let i=0;i<6;i++){let px=x+S*Math.cos((60*i-30)*Math.PI/180),py=y+S*Math.sin((60*i-30)*Math.PI/180);if(i)ctx.lineTo(px,py);else ctx.moveTo(px,py)}ctx.closePath();ctx.clip();ctx.fillStyle='#123126';ctx.fillRect(x-W/2,y-S,W,2*S);let img=artwork(tileArt(t)),artWidth=['lander','dropship'].includes(t.terrain)?Math.sqrt(3)*S:W;if(img.complete&&img.naturalWidth)ctx.drawImage(img,x-artWidth/2,y-S,artWidth,2*S);else if(t.known){ctx.fillStyle='#d8f3df';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(label(t.terrain),x,y+4)}ctx.restore()}
 let warning=document.querySelector('.art-warning');if(warning){warning.hidden=!artFailures.size;warning.textContent=artFailures.size?'Embedded tile artwork could not be decoded on this device.':''}}
function cargoIcon(x,y,count){return `<g class="cargo-marker" transform="translate(${x} ${y})" aria-label="${count?`${count} dropped equipment`:'Equipment cache'}"><rect x="-12" y="-10" width="24" height="20" rx="5" fill="#302d23" stroke="#ffd274" stroke-width="2"/><path d="M-5-9v18 M5-9v18" stroke="#ad8550" stroke-width="2"/><path d="M0-5L5 0 0 5-5 0Z" fill="#ffe18c"/>${count?`<circle cx="10" cy="-10" r="8" fill="#ffe18c"/><text x="10" y="-6" class="cargo-count">${count}</text>`:''}</g>`}
function flareIcon(x,y){return `<g class="flare-marker" transform="translate(${x} ${y})" aria-label="Burning flare with smoke"><circle class="flare-aura" cy="7" r="20"/><path class="flare-smoke smoke-a" d="M-3-4 Q-17-16-5-29 Q6-38-1-50"/><path class="flare-smoke smoke-b" d="M4-3 Q17-16 7-27 Q-4-35 8-48"/><path class="flare-smoke smoke-c" d="M0-8 Q-6-18 2-31 Q11-39 3-51"/><path d="M-5 12L4-8L9-5L0 15Z" fill="#e5ae5c" stroke="#4b2517" stroke-width="1.4"/><circle class="flare-core" cx="6" cy="-7" r="6"/></g>`}
function signalIcon(x,y){return `<g class="signal-icon" transform="translate(${x} ${y})" aria-label="Distress transmission"><circle r="15" fill="#062923" stroke="#72e7d3" stroke-width="1.5"/><circle cx="0" cy="7" r="2.8" fill="#9dffee"/><path class="signal-wave wave-1" d="M-5 3Q0-4 5 3"/><path class="signal-wave wave-2" d="M-9 2Q0-10 9 2"/><path class="signal-wave wave-3" d="M-13 1Q0-16 13 1"/></g>`}
function board(){const S=55,X=360,Y=315;let out=['<svg viewBox="20 8 680 614" role="img" aria-label="Hexagonal alien planet board"><defs><radialGradient id="fogGrad"><stop offset="0" stop-color="#226c4b"/><stop offset=".55" stop-color="#184b3d"/><stop offset="1" stop-color="#0a2b25"/></radialGradient></defs>'];for(let c of CELLS){let t=tile(c.k),x=X+Math.sqrt(3)*S*(c.q+c.r/2),y=Y+1.5*S*c.r,id=c.k.replace(',','_');let pts=Array.from({length:6},(_,i)=>`${x+S*Math.cos((60*i-30)*Math.PI/180)},${y+S*Math.sin((60*i-30)*Math.PI/180)}`).join(' '),valid=!!ui.mode&&targetValid(c.k);
 out.push(`<g data-hex="${c.k}" style="--player-color:${COLOURS[s.turn]}"><defs><clipPath id="clip_${id}"><polygon points="${pts}"/></clipPath></defs><polygon points="${pts}" fill="transparent"/>`);
 if(!t.known||ui.revealing[c.k])out.push(`<g class="dark-layer ${ui.revealing[c.k]?'illuminating':''}" clip-path="url(#clip_${id})" pointer-events="none"><polygon points="${pts}" fill="#020907"/><path d="M${x-38} ${y+16}l19-8 18 5 23-15 M${x-18} ${y-30}l13 9 21-5" fill="none" stroke="#183127" stroke-width="1" opacity=".45"/></g>`);
 out.push(`<polygon class="hex ${ui.selected===c.k?'sel':''} ${s.alien===c.k&&t.known?'danger':''} ${valid?'target':''} ${ui.targetHex===c.k?'chosen':''} ${s.phase==='play'&&me().pos===c.k?'active-player':''} ${!ui.mode&&dist(me().pos,c.k)===1&&s.moves>0&&!me().captive?'reach':''}" points="${pts}" fill="none" pointer-events="all"/>`);
 if(t.known){if(t.site?.status==='hidden')out.push(t.site.kind==='cargo'?cargoIcon(x-29,y-25):signalIcon(x-29,y-25));if(t.site?.status==='found'||t.groundScientists)out.push(`<text class="marker scientist-marker" x="${x-28}" y="${y-22}" fill="#c5ffe1">✚</text>`);if(t.loose.length)out.push(cargoIcon(x+27,y-26,t.loose.length))}
 else if((t.site?.decoy&&t.site.status==='hidden')||t.intel)out.push(signalIcon(x-29,y-25));
 s.players.forEach((p,i)=>{if(p.pos!==c.k||!t.known)return;let n=s.players.slice(0,i).filter(a=>a.pos===c.k).length,tx=x-21+(n%3)*21,ty=y+25+Math.floor(n/3)*20,initial=esc((p.name.trim().charAt(0)||'?').toUpperCase());out.push(`<g class="crew-token ${p.captive?'captive':''}" transform="translate(${tx} ${ty})" style="--piece-color:${COLOURS[i]}" aria-label="${esc(p.name)}${p.scientist?' escorting a scientist':''}"><circle class="helmet-rim" r="13"/><circle r="10" fill="#10221f"/><ellipse cy="-2" rx="8" ry="5" fill="#285052"/><path d="M-3-11L0-15 3-11" fill="var(--piece-color)"/><text class="crew-initial" y="5">${initial}</text>${p.scientist?'<circle cx="10" cy="-10" r="6" fill="#f6fff7"/><text class="scientist-tag" x="10" y="-7">✚</text>':''}</g>`)});
 if(s.flares.some(f=>f.hex===c.k))out.push(flareIcon(x+8,y+8));
out.push('</g>')}out.push(alienIcon());out.push('</svg>');return out.join('')}
function hexCentre(k){let c=MAP[k];return [360+Math.sqrt(3)*55*(c.q+c.r/2),315+82.5*c.r]}
function alienIcon(){let motion=ui.alienMotion;if(!motion&&!tile(s.alien).known)return '';let from=motion?.from||s.alien,to=motion?.to||s.alien;if(!tile(from).known&&!tile(to).known)return '';let a=hexCentre(from),b=hexCentre(to),progress=motion?Math.min(1,(Date.now()-motion.started)/motion.duration):1,x=a[0]+(b[0]-a[0])*progress,y=a[1]+(b[1]-a[1])*progress,seconds=motion?Math.max(.001,(motion.duration-(Date.now()-motion.started))/1000):0;let opacity=tile(from).known?tile(to).known?1:Math.max(0,1-progress*5):Math.max(0,(progress-.8)*5);return `<g class="alien-travel" transform="translate(${x} ${y})" opacity="${opacity}" pointer-events="none" aria-label="Alien creature">${motion?`<animateTransform attributeName="transform" type="translate" from="${x} ${y}" to="${b[0]} ${b[1]}" dur="${seconds}s" fill="freeze"/><animate attributeName="opacity" values="${opacity};${tile(to).known?1:0}" dur="${Math.min(seconds,.2)}s" begin="${!tile(from).known?Math.max(0,seconds-.2):0}s" fill="freeze"/>`:''}<g class="alien-presence" transform="translate(27 -25)"><circle class="alien-halo" r="18"/><path class="alien-core" d="M0-12C8-12 13-7 12 1 12 8 6 13-2 12-10 11-14 5-12-2-11-9-6-12 0-12Z"/><circle class="alien-heart" r="5"/></g></g>`}
const hoursLeft=()=>Math.max(0,10-s.round);
function dieOverlay(){return ui.rolling||ui.dieSettled?`<div class="die-stage ${ui.rolling?'rolling':'settled'}" role="status" aria-label="${ui.rolling?'Die rolling':`Rolled ${ui.escapeRoll}`}"><div class="travelling-die">${dieFace(ui.rolling?null:ui.escapeRoll)}</div>${ui.dieSettled?`<strong class="roll-caption">${ui.escapeRoll} · ${ui.escapeRoll%2?'Still captive':'Escaped'}</strong>`:''}</div>`:''}
function dieFace(n){let spots={1:[[21,21]],2:[[11,11],[31,31]],3:[[11,11],[21,21],[31,31]],4:[[11,11],[31,11],[11,31],[31,31]],5:[[11,11],[31,11],[21,21],[11,31],[31,31]],6:[[11,10],[31,10],[11,21],[31,21],[11,32],[31,32]]};return `<svg class="die-face" viewBox="0 0 42 42" role="img" aria-label="Alien die${n?` showing ${n}`:''}"><rect x="2" y="2" width="38" height="38" rx="9" fill="#3fc673" stroke="#a3ffb4" stroke-width="2"/>${(spots[n]||[]).map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.5" fill="#072b1b"/>`).join('')}${!n?'<text x="21" y="29" text-anchor="middle" font-size="24" font-weight="bold" fill="#0a3520">?</text>':''}</svg>`}
function buttons(){let p=me(),t=tile(p.pos),sel=tile(ui.selected),b=[];const add=(name,act,disabled=false,wide=false,cl='')=>b.push(`<button class="${wide?'wide ':''}${cl}" data-act="${act}" ${disabled||s.ap<1?'disabled':''}>${name}</button>`);
 if(p.captive){let rolled=p.rolledRound===s.round?p.lastRoll:null;b.push(`<button class="wide alien-die" data-act="escape" ${rolled?'disabled':''}>${dieFace(rolled)}<span>${rolled?`Rolled ${rolled}`:'Roll alien d6'}</span></button><p class="die-help">Even: escape with two moves and no action. Odd: remain captive.</p>`);b.push('<button class="wide ghost" data-act="end">End turn</button>');return b.join('')}
 if(t.site?.status==='hidden')add(t.site.kind==='cargo'?'Search equipment':'Search signal','search',t.site.kind==='cargo'&&p.cargo.length>=2);
 if((t.site?.status==='found'||t.groundScientists)&&!p.scientist)add('Escort scientist','escort');if(p.scientist&&p.pos===DROPSHIP)add('Deliver scientist','deliver');
 s.players.forEach((other,i)=>{if(other.captive&&dist(p.pos,NEST)<=1)add(`Free ${esc(other.name)}`,`free:${i}`)});
 if(t.loose.length&&p.cargo.length<2)t.loose.forEach((_,i)=>add(`Pick up equipment ${i+1}`,`collect:${i}`));
 if(sel?.known&&sel.terrain==='bridge'&&dist(p.pos,ui.selected)<=1)add('Collapse selected bridge','collapse',!canCollapse(ui.selected));
 if(s.scans>0)add(`Scan inventory (${s.scans})`,'scan',false,true);
 if(p.cargo.length)add('Pass or snatch inventory','transfer',false,true);
 if(p.role==='saboteur')b.push('<button class="wide quiet" data-act="privateActions">Private actions</button>');
 if(s.delivered===2&&p.pos===DROPSHIP)add('Call for launch','launch',false,true,'primary');
 b.push('<button class="wide ghost" data-act="end">End turn</button>');return b.join('')}
function inventoryPanel(){let p=me();return `<div class="inventory-panel" aria-label="Player inventory"><h3>Inventory</h3>${[0,1].map(i=>{let v=p.cargo[i];return `<div class="inventory-slot ${v?'filled':'empty'}"><div class="slot-main"><span class="slot-number">${i+1}</span><span class="slot-name"><small>INVENTORY ${i+1}</small><strong>${v?esc(v.toUpperCase()):'EMPTY'}</strong></span></div>${v?`<div class="slot-controls">${USABLE.includes(v)?`<button class="slot-use" data-act="chooseItem:${i}" ${s.ap<1||p.captive?'disabled':''}>Use ${esc(v)}</button>`:''}${v==='specimen'?`<button class="slot-use" data-act="research:${i}" ${s.ap<1||p.captive?'disabled':''}>Research</button>`:''}<button data-act="drop:${i}" ${s.ap<1||p.captive?'disabled':''}>Drop</button>${p.pos===HOME?`<button class="danger" data-act="burn:${i}" ${s.ap<1||p.captive?'disabled':''}>Incinerate</button>`:''}</div>`:''}</div>`}).join('')}</div>`}
function extra(){let p=me(),out='';if(ui.scan){let choices=s.players.flatMap((o,i)=>o.pos===p.pos?o.cargo.map((_,j)=>`<button data-act="scan:${i}:${j}">${esc(o.name)} · inventory ${j+1}</button>`):[]);out+=`<div class="panel"><h3>Choose inventory slot to scan</h3><div class="stack">${choices.join('')||'No inventory items here.'}</div></div>`}
 if(ui.transfer){let choices=s.players.flatMap((o,i)=>i===s.turn?[]:[...(o.pos===p.pos?p.cargo.map((_,j)=>`<button data-act="give:${i}:${j}">Give inventory ${j+1} to ${esc(o.name)}</button>`):[]),...(dist(o.pos,p.pos)<=1&&o.cargo.length&&p.cargo.length<2?[`<button data-act="steal:${i}">Snatch random inventory from ${esc(o.name)}</button>`]:[])]);out+=`<div class="panel"><h3>Pass or snatch inventory</h3><div class="stack">${choices.join('')||'No valid transfer nearby.'}</div></div>`}return out}
function targetPanel(){if(!ui.mode)return buttons();let item=ui.mode==='itemTarget'?me().cargo[ui.itemIndex]:null;let label=ui.mode==='itemTarget'?`Use ${item?.toUpperCase()||'ITEM'}`:ui.mode==='decoy'?'Place distress signal':'Redirect alien';return `<div class="target-panel"><h3>${label}</h3><p>Tap a glowing hex to choose the target. Nothing happens until you confirm.</p><p class="notice">${ui.targetHex?`Target: ${ui.targetHex}`:'Choose a highlighted hex'}</p><div class="actions"><button class="primary" data-act="confirmTarget" ${!ui.targetHex?'disabled':''}>Confirm target</button><button data-act="cancelTarget">Cancel</button></div></div>`}
function privateOverlay(){let p=me(),kind=ui.privateKind||'result',content='';if(kind==='briefing'){let sab=p.role==='saboteur';content=`<p class="order-classification">${sab?'CORPORATION · EYES ONLY':'COLONIAL MARINES · PRIVATE ORDERS'}</p><h2>${sab?'Corporation Executive Order':`Private Orders for ${rank(s.turn)} ${esc(p.name)}`}</h2><p class="order-recipient">${rank(s.turn)} ${esc(p.name)} · ${personnel(s.turn)}</p><div class="order-directive"><p>${sab?'Secure an Alien Egg and return it aboard the Dropship. If unable to locate one, your orders are to prevent the scientists from leaving the planet. We cannot afford their research to become ‘known’. All other personnel are expendable. You have 9 hours until Dropship launch.':s.turn===0?'Good luck, Sergeant.':'Work together. Sweep and clear. Find the scientists and bring them home.'}</p></div>`}
 if(ui.privateResult)content+=`<h2>Private result</h2><p class="notice">${esc(ui.privateResult)}</p>`;
 if(kind==='actions')content=`<h2>Private actions</h2>${p.role==='saboteur'?`<p>These options are visible only to you. Effects resolve at the end of the hour without naming you.</p><div class="stack"><button data-act="jam" ${!s.ap||!s.scans?'disabled':''}>Disable one scan charge</button><button data-act="decoy" ${!s.ap||!s.decoys?'disabled':''}>Plant false distress signal (${s.decoys} left)</button><button data-act="redirect" ${!s.ap?'disabled':''}>Redirect the creature</button></div>`:'<p>Work together. Sweep and clear.</p>'}`;
 return `<div class="overlay ${kind==='briefing'?'executive-overlay':''}"><div class="card private ${kind==='briefing'?'executive-order crt':''}"><div class="private-content">${content}</div><button class="primary" data-act="closePrivate">${kind==='briefing'?'Begin turn':'Hide private view'}</button></div></div>`}
function barcode(code){let x=0,bars='';for(let c of code){for(let bit=6;bit>=0;bit--){let w=(c.charCodeAt(0)&1<<bit)?3:1.5;bars+=`<rect x="${x}" y="0" width="${w}" height="26"/>`;x+=w+1.2}x+=2.5}return `<svg viewBox="0 0 ${x} 26" preserveAspectRatio="none" aria-hidden="true">${bars}</svg>`}
function personnelCard(){let code=personnel(s.turn);return `<div class="personnel-card"><div class="personnel-caption">ROYAL SPACE MARINES</div><div class="personnel-main"><span class="rank-chevron" aria-hidden="true">${s.turn===0?'❯❯❯':'❯'}</span><div><strong>${rank(s.turn)} ${esc(me().name.toUpperCase())}</strong><small>CORPORATION PERSONNEL · ${code}</small></div></div><div class="personnel-barcode">${barcode(code)}<span>${code}</span></div></div>`}
function handoffBoard(){let p=me();return `<main class="layout"><section class="board"><canvas class="terrain-canvas" width="680" height="614" aria-hidden="true"></canvas>${board()}<div class="art-warning" hidden></div><div class="handoff-shade"></div><div class="handoff-prompt" style="--player-color:${COLOURS[s.turn]}"><h2>${p.briefed?`Pass to ${esc(p.name)}`:`Private Orders for ${rank(s.turn)} ${esc(p.name)}`}</h2><p>${hoursLeft()} ${hoursLeft()===1?'hour':'hours'} until dropship departure</p>${s.alert?`<p class="notice">${esc(s.alert)}</p>`:''}<button class="primary" data-act="${p.briefed?'startTurn':'reveal'}">${p.briefed?'Start turn':`I am ${esc(p.name)} · view orders`}</button></div></section><aside class="side player-flip" style="--player-color:${COLOURS[s.turn]}"><div class="flip-inner is-back"><div class="flip-face flip-front"></div><div class="flip-face flip-back"><span class="alien-emblem">◈</span><strong>THE LAST SHIP</strong><span>Awaiting next player</span></div></div></aside></main>`}
function heartMonitor(){let p=me(),d=dist(p.pos,s.alien),level=p.captive||d<=1?'critical':d===2?'rapid':d===3?'elevated':'steady',info={steady:['STEADY',62],elevated:['ELEVATED',78],rapid:['RAPID',104],critical:['CRITICAL',132]}[level];
 let pulse='M0 40 L66 40 72 37 78 43 86 40 100 40 108 51 116 13 124 58 132 40 146 40 152 37 159 43 166 40 240 40';
 return `<div class="heart-monitor ${level}" style="--beat-time:${60/info[1]}s" role="img" aria-label="${esc(p.name)} heart rate ${info[1]} beats per minute, ${info[0].toLowerCase()} alien proximity"><div class="monitor-title"><span>BIOSUIT · HEART RATE</span><strong>${info[1]} <small>BPM</small></strong></div><div class="monitor-screen"><svg viewBox="0 0 240 80" preserveAspectRatio="none" aria-hidden="true"><path d="${pulse}"><animate attributeName="d" dur="${60/info[1]}s" repeatCount="indefinite" values="M0 40 L66 40 72 40 78 40 86 40 100 40 108 40 116 40 124 40 132 40 146 40 152 40 159 40 166 40 240 40;${pulse};${pulse};M0 40 L66 40 72 40 78 40 86 40 100 40 108 40 116 40 124 40 132 40 146 40 152 40 159 40 166 40 240 40" keyTimes="0;.15;.4;1"/></path></svg><span class="scan-line"></span></div><div class="monitor-foot"><span class="status-light"></span>${info[0]}<span class="monitor-foot-right">LIFE SIGNS</span></div></div>`}
function render(){if(ui.note&&!ui.mode&&ui.note!==ui.timedNote){ui.timedNote=ui.note;let message=ui.note,game=s;setTimeout(()=>{if(s===game&&ui.note===message&&!ui.mode){ui.note='';render()}},5000)}let root=document.getElementById('app');if(!s){root.innerHTML=`<main class="screen terminal-screen"><div class="card crt roster"><p class="order-classification">PERSONNEL TERMINAL · CREW REGISTRATION</p><h1>Colonial Marines Crew Roster</h1><h2>Dropship: UKSS APATE</h2><div id="names" class="stack">${[1,2,3,4].map(i=>`<div class="field"><span class="setup-rank">${rank(i-1)}</span><input aria-label="${rank(i-1)} player ${i} name" value="${['Xenia','Zander','Emma','Jim'][i-1]}"></div>`).join('')}</div><div class="row"><button data-act="add">Add player</button><button class="primary" data-act="start">Start game</button></div><details class="rules"><summary>How to play</summary><p>Each turn has two moves and one action. Tap a neighbouring hex to move. Entering a Gravity Hole transports you to its matching pair. An event tile ends movement on first entry.</p><p>The alien moves two hexes at round end. On contact it drags a player to the nest. Roll an even number on the alien die to escape.</p></details></div></main>`;bind();return}
 if(s.phase==='briefing'){root.innerHTML=`<main class="screen terminal-screen"><div class="card crt shared-order"><p class="order-classification">UKSS APATE · MISSION PRIORITY: SCIENTIST EXTRACTION</p><h1>Colonial Marines Order 1592-B</h1><div class="order-directive"><p>Locate both scientists and escort them safely aboard the Dropship.</p><p>Under no circumstances is an Alien Egg to leave the planet.</p><p>The Dropship departs in 9 hours. Protect your team and complete the extraction before launch.</p></div><button class="primary" data-act="ackMission">Acknowledge</button></div></main>`;bind();return}
 if(s.phase==='handoff'){root.innerHTML=handoffBoard();drawTerrain();bind();return}
 if(s.phase==='over'){root.innerHTML=`<main class="screen"><div class="card"><h1>${s.winner==='crew'?'CREW ESCAPED':'SABOTEUR WINS'}</h1><p class="score">${esc(s.log[0])}</p><p>Saboteur: <strong>${esc(s.players.find(p=>p.role==='saboteur').name)}</strong>. Scientists delivered: ${s.delivered}/2. Egg ${s.eggDestroyed?'destroyed':'not destroyed'}.</p><button class="primary" data-act="reset">Play again</button><h3>Final events</h3><div class="log">${s.log.slice(0,12).map(x=>`<div>${esc(x)}</div>`).join('')}</div></div></main>`;bind();return}
 if(s.phase==='launch'){let waiting=s.players.map((p,i)=>({p,i})).filter(o=>o.p.pos===DROPSHIP&&!o.p.captive);root.innerHTML=`<main class="screen"><div class="card"><h1>FINAL DEPARTURE</h1><p>Both scientists are aboard. Discuss who boards. Return to the board to use remaining scans.</p><div class="choices">${waiting.map(({p,i})=>`<label><input class="boarding" type="checkbox" value="${i}" checked> ${esc(p.name)} · ${p.cargo.length} inventory items</label>`).join('')}</div><div class="row"><button class="primary" data-act="depart">Close hatch · reveal</button><button data-act="cancelLaunch">Back to board</button></div></div></main>`;bind();return}
 let p=me();root.innerHTML=`<main class="layout"><section class="board"><canvas class="terrain-canvas" width="680" height="614" aria-hidden="true"></canvas>${board()}<div class="art-warning" hidden></div>${ui.note?`<div class="board-message" role="status">${esc(ui.note)}</div>`:''}${dieOverlay()}${s.phase==='alien'?'<div class="alien-activity">ALIEN ACTIVITY</div>':''}<div class="board-stats" aria-label="Game progress"><span class="pill">Hours left <b>${hoursLeft()}</b></span><span class="pill">Scientists <b>${s.delivered}/2</b></span><span class="pill">Scans <b>${s.scans}</b></span></div></section><aside class="side player-flip" style="--player-color:${COLOURS[s.turn]}"><div class="flip-inner ${s.phase==='alien'?'is-back':ui.flipping==='out'?'flip-out':ui.flipping==='in'?'flip-in':''}"><div class="flip-face flip-front"><div class="panel player-panel"><h2>Actions</h2><div class="turn-status"><div class="status-card moves-card" aria-label="Moves left ${s.moves}"><svg class="boot-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M7 2Q10 1 12 4L14 13Q13 17 9 17L6 14L4 6Q3 3 7 2ZM19 14Q23 12 25 15L29 23Q30 27 27 29L21 30Q17 30 16 26L17 18Q17 15 19 14Z"/><path d="M5 19L12 18M16 12L24 10" fill="none" stroke="currentColor" stroke-width="1.7"/></svg><span><small>MOVES LEFT</small><b>${s.moves}</b></span></div><div class="status-card action-card ${s.ap?'ready':'used'}" aria-label="${s.ap?`${s.ap} actions ready`:'Action used'}"><span class="status-icon" aria-hidden="true">${s.ap?'✓':'—'}</span><span><small>${s.ap>1?'ACTIONS':'ACTION'}</small><b>${s.ap>1?`${s.ap} ready`:s.ap?'ready':'used'}</b></span></div></div>${p.scientist?'<div class="escort-badge"><span>✚</span> Escorting scientist</div>':''}${p.captive?'<p class="notice">CAPTIVE AT THE NEST</p>':''}${ui.escapeRoll&&!p.captive?`<div class="die-result">${dieFace(ui.escapeRoll)}<span>Escaped on ${ui.escapeRoll}</span></div>`:''}<div class="actions">${targetPanel()}</div></div>${extra()}${inventoryPanel()}<details class="panel rules"><summary>Rules and terrain</summary><p>Two moves and one action, in any order. Event tiles end movement on first entry, then become open ground. Bridges can collapse. Enter a Gravity Hole to emerge at its pair for one move; move off it before using it again. Cover hides from nearest-target selection unless you make noise. Spores create noise.</p><p>The alien moves up to two hexes at the end of each hour. It stalks through dark terrain before attacking, then withdraws after a capture. Noise, flares and sabotage signals interrupt stalking. Its icon is visible only on explored hexes. Flare smoke burns through the current and next round. Researching a specimen spends an action and privately alters a future turn. Contact sends a player to the nest. Their scientist drops where caught; their inventory becomes dropped equipment there, or on a neighbouring safe hex if caught on a Gravity Hole. Roll an even number on the alien d6 next turn to escape with two moves and no action; an ally beside the nest can use an action to free them.</p><p>Amber canister: equipment · pulsing transmission: distress · ✚ scientist · glowing shape: alien. Crew must launch both scientists without the egg. The saboteur wins if the egg boards or the departure window closes.</p></details>${personnelCard()}${heartMonitor()}</div><div class="flip-face flip-back"><span class="alien-emblem">◈</span><strong>THE LAST SHIP</strong><span>Pass the iPad</span></div></div></aside></main>`;
 if(ui.private||ui.privateResult)root.innerHTML+=privateOverlay();
 if(s.pendingEvent&&!ui.sequence&&!ui.popup){let msg=s.pendingEvent==='Risky salvage'?'Take a jetpack, but the alien moves one hex toward you?':'Reveal one distress signal, but spend one scan charge if available?';root.innerHTML+=`<div class="overlay"><div class="card"><h2>EVENT CHOICE</h2><p>${msg}</p><div class="row"><button class="primary" data-act="eventYes">Take the risk</button><button data-act="eventNo">Leave it</button></div></div></div>`}
 root.innerHTML+=popupMarkup();drawTerrain();bind()}
function bind(){document.querySelectorAll('[data-hex]').forEach(el=>el.addEventListener('click',()=>{let k=el.dataset.hex;if(s.phase!=='play'||s.pendingEvent||ui.sequence||ui.popup||ui.flipping||ui.rolling||ui.private||ui.privateResult)return;if(ui.mode){if(targetValid(k)){ui.targetHex=k;ui.note=`Target ${k} selected. Confirm or cancel.`}else ui.note='Choose a glowing valid hex.';render();return}let p=me();if(s.moves>0&&!p.captive&&dist(p.pos,k)===1){move(k);return}ui.selected=k;render()}));document.querySelectorAll('[data-act]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.act)))}
function act(a){if(ui.sequence||ui.popup||s?.phase==='alien')return;if(a==='add'){let n=document.querySelectorAll('#names input').length;if(n>=6)return;document.querySelector('#names').insertAdjacentHTML('beforeend',`<div class="field"><span class="setup-rank">${rank(n)}</span><input aria-label="${rank(n)} player ${n+1} name" value="Player ${n+1}"></div>`);return}
 if(a==='start'){if(ui.fading)return;let names=[...document.querySelectorAll('#names input')].map(x=>x.value.trim()).filter(Boolean);if(names.length<4)return alert('Add at least four player names.');ui.fading=true;document.getElementById('app').classList.add('fade-black');setTimeout(()=>{document.getElementById('app').classList.remove('fade-black');newGame(names)},650);return}if(a==='reset'){if(confirm('Start a new game?')){localStorage.removeItem(KEY);s=null;render()}return}
 if(a==='ackMission'){if(s.phase!=='briefing')return;s.phase='handoff';finish();return}
 if(a==='reveal'||a==='startTurn'){if(s.phase!=='handoff')return;let first=!me().briefed;s.phase='play';ui.private=false;ui.privateKind='';ui.flipping='in';finish();setTimeout(()=>{ui.flipping='';if(first){ui.private=true;ui.privateKind='briefing'}finish()},1000);return}
 if(ui.flipping||ui.rolling)return;
 if(a==='closePrivate'){if(ui.privateKind==='briefing')me().briefed=true;save();ui.private=false;ui.privateKind='';ui.privateResult='';render();return}
 if(ui.privateKind==='briefing')return;
 if(a==='privateActions'){ui.private=true;ui.privateKind='actions';render();return}
 if(a==='eventYes'||a==='eventNo'){chooseEvent(a==='eventYes');return}if(a==='cancelLaunch'){s.phase='play';finish();return}if(a==='depart'){finishLaunch();return}if(a==='end'){flipEndTurn();return}
 if(s.pendingEvent||s.phase!=='play')return;
 if(a==='confirmTarget'){if(!ui.targetHex)return;if(ui.mode==='itemTarget')return useItem();if(ui.mode==='decoy')return plant(ui.targetHex);if(ui.mode==='redirect')return redirect(ui.targetHex)}
 if(a==='cancelTarget'){cancelTarget();return}
 if(a==='jam'){jamScan();return}if(a==='decoy'){if(me().role!=='saboteur')return;ui.private=false;ui.privateKind='';ui.mode='decoy';ui.targetHex=null;return notice('Choose an adjacent hex for a false signal, then confirm.')}if(a==='redirect'){if(me().role!=='saboteur')return;ui.private=false;ui.privateKind='';ui.mode='redirect';ui.targetHex=null;return notice('Choose a hex within two spaces, then confirm.')}
 if(a==='search')return search();if(a==='escort')return escort();if(a==='deliver')return deliver();if(a==='escape')return escapeNest();if(a==='collapse')return collapse(ui.selected);if(a==='scan'){ui.scan=!ui.scan;ui.transfer=false;render();return}if(a==='transfer'){ui.transfer=!ui.transfer;ui.scan=false;render();return}if(a==='launch')return launch();
 let [type,x,y]=a.split(':');if(type==='chooseItem')return beginItem(+x);if(type==='research')return researchSpecimen(+x);if(type==='free')return freeCaptive(+x);if(type==='collect')return collect(+x);if(type==='drop')return drop(+x);if(type==='burn')return incinerate(+x);if(type==='scan')return scan(+x,+y);if(type==='give')return transfer(+x,+y,false);if(type==='steal')return transfer(+x,0,true)}
 render();if(s?.phase==='alien'){s.alienMovesLeft??=2;runAlienTurn()}
})();
